import type { AnalyticsClientType, AnalyticsPlatform } from "./clients.js";
import type { AnalyticsEventName } from "./events.js";

/** Bumped on any breaking change to the envelope or the event table. */
export const ANALYTICS_SCHEMA_VERSION = 1 as const;

/** Most events one batch may carry, on the client and at ingestion. */
export const MAX_BATCH_EVENTS = 50;

/**
 * One event exactly as it is serialized and sent. `timestamp` is truncated to
 * the hour. `anonymousId` and `sessionId` are random UUIDs generated by the
 * client, and are `null` for `cloud_backend`, which has no analytics identity.
 */
export interface AnalyticsEnvelope {
  schemaVersion: typeof ANALYTICS_SCHEMA_VERSION;
  event: AnalyticsEventName;
  clientType: AnalyticsClientType;
  anonymousId: string | null;
  sessionId: string | null;
  timestamp: string;
  appVersion: string;
  platform: AnalyticsPlatform;
  properties: Record<string, string>;
}

/** The request body of `POST /api/analytics/v1/events`. */
export interface AnalyticsBatch {
  schemaVersion: typeof ANALYTICS_SCHEMA_VERSION;
  events: AnalyticsEnvelope[];
}

/** The ingestion path, relative to a NodeTool server or the analytics host. */
export const ANALYTICS_INGEST_PATH = "/api/analytics/v1/events";

/** Where relaying servers and the CLI send batches unless configured otherwise. */
export const DEFAULT_ANALYTICS_ENDPOINT = `https://analytics.nodetool.ai${ANALYTICS_INGEST_PATH}`;

/** The envelope keys, in serialization order. Nothing else is accepted. */
export const ENVELOPE_KEYS = [
  "schemaVersion",
  "event",
  "clientType",
  "anonymousId",
  "sessionId",
  "timestamp",
  "appVersion",
  "platform",
  "properties"
] as const satisfies readonly (keyof AnalyticsEnvelope)[];

/** Truncate a time to the start of its UTC hour, as an ISO string. */
export function hourTimestamp(date: Date): string {
  const copy = new Date(date.getTime());
  copy.setUTCMinutes(0, 0, 0);
  return copy.toISOString();
}
